   224  static void
   225  skip_buffer_input_data(j_decompress_ptr cinfo, long num_bytes)
   226  {
   227      if (num_bytes < 0)
   228      {
   229          throw std::runtime_error(
   230              "reading jpeg: jpeg library requested"
   231              " skipping a negative number of bytes");
   232      }
   233      size_t to_skip = QIntC::to_size(num_bytes);
   234      if ((to_skip > 0) && (to_skip <= cinfo->src->bytes_in_buffer))
   235      {
   236          cinfo->src->next_input_byte += to_skip;
   237          cinfo->src->bytes_in_buffer -= to_skip;
   238      }
   239      else if (to_skip != 0)
   240      {
   241          cinfo->src->next_input_byte += cinfo->src->bytes_in_buffer;
   242          cinfo->src->bytes_in_buffer = 0;
   243      }
   244  }
